  'cs.no_rubrics_sub': 'ଆପଣ ଗୋଟିଏ ଖେଳର କୋଚିଂ କଲେ (ଦଳରେ ଯୋଗ ଦିଅନ୍ତୁ ବା ତିଆରି କରନ୍ତୁ, କିମ୍ବା କୋଚ୍ ଖେଳ ପ୍ରୋଫାଇଲ୍ ଯୋଡ଼ନ୍ତୁ) ମାନକ ରୁବ୍ରିକ୍ ଦେଖାଯିବ। କିମ୍ବା ନିଜର ତିଆରି କରନ୍ତୁ, ତାପରେ ଅଧିବେଶନ ବେଳେ ନୋଟ୍ ସିଟ୍‌ରୁ ଖେଳାଳିଙ୍କୁ ସ୍କୋର୍ ଦିଅନ୍ତୁ।',
